# IR funkcni analyzy add-inu EA File Bridge (as-implemented z kodu src @ v0.21 + pump.wsf v0.6).
# Rozsah rozsiren Milosem 14. 10. 2026 20:00: UC vc. scenaru, pravidel, UCR a logickych obrazovek (menu, okna).
ACTORS = [
 ("AI agent", "Agent (Copilot ve VS Code, M365 Copilot nebo jiný klient), který skládá dávky protokolu eafb/0.2 a čte odpovědi. Primární aktér zpracování dávek."),
 ("Analytik", "Uživatel EA, který spouští menu AI Bridge, potvrzuje nebo zamítá dávky v okně pumpy a předává agentovi kontext výběru."),
 ("Správce bridge", "Správce repozitáře / vývojář bridge: nasazuje kód do modelu, spravuje politiku rizik, cíl zápisu a úklid záloh."),
]
def S(text, kind="system", uses=""): return {"text": text, "kind": kind, **({"uses": uses} if uses else {})}
def SC(name, type_, steps, attach=None, join=None, notes=""):
    d = {"name": name, "type": type_, "steps": steps}
    if attach: d["attachTo"] = {"scenario": attach[0], "step": attach[1]}
    if join is not None: d["join"] = join
    if notes: d["notes"] = notes
    return d

